local Tower = require("data.tower")
local FONT = "sarasa-mono-sc-regular"
local function checkpointLabel(id)
    do
        local i = 0
        while i < #Tower.checkpoints do
            if Tower.checkpoints[i + 1].id == id then
                return (Tower.FLOORS[Tower.checkpoints[i + 1].floor + 1] .. "·") .. Tower.checkpoints[i + 1].label
            end
            i = i + 1
        end
    end
    return id
end
local PANEL_TEX = "assets/ui/panel.png"
local PANEL_W = 880
local PANEL_H = 500
local PANEL_COLS = 7
local PANEL_ROWS = 4
local function loadTex(path)
    return Texture2D(path)
end
local function pxSprite(tex)
    local sp = Sprite(tex)
    sp.filter = "Point"
    return sp
end
local function col(c)
    return Color(c.r, c.g, c.b, c.a)
end
local function makeLabel(parent, size, x, y, ax, ay, color)
    local lb = Label(FONT, size)
    if lb == nil then
        return nil
    end
    lb.anchor = Vec2(ax, ay)
    lb.position = Vec2(x, y)
    lb.color = Color(color.r, color.g, color.b, color.a)
    lb:addTo(parent)
    return lb
end
local function setText(lb, text)
    if lb ~= nil and lb.text ~= text then
        lb.text = text
    end
end
